<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#17233d}h1{font-size:17px;margin:0 0 4px}.meta{color:#64748b;margin-bottom:14px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:6px;text-align:left}th{background:#0b234b;color:white;font-size:8px}.pending{color:#b45309}.foot{margin-top:12px;color:#64748b;font-size:8px}</style></head><body><h1>{{ $exam->title }} — CBT Result Report</h1><div class="meta">{{ $exam->questionBank->subject->name ?? '' }} · {{ $exam->classArm->classLevel->name ?? '' }} {{ $exam->classArm->name ?? '' }} · {{ $exam->term->name ?? '' }} · Generated {{ now()->format('d M Y, H:i') }}</div><table><thead><tr><th>Student</th><th>Admission No.</th><th>Attempt</th><th>Status</th>@foreach($exam->sections as $section)<th>{{ $section->code }} · {{ $section->name }}</th>@endforeach<th>Total</th><th>%</th></tr></thead><tbody>@foreach($sessions as $session)<tr><td>{{ $session->student->full_name }}</td><td>{{ $session->student->admission_number }}</td><td>{{ $session->attempt_number }}</td><td>{{ str_replace('_',' ',$session->status) }}</td>@foreach($exam->sections as $section)@php $sa=$session->sectionAttempts->firstWhere('cbt_exam_section_id',$section->id); @endphp<td class="{{ !$sa||$sa->status!=='scored'?'pending':'' }}">{{ $sa&&$sa->status==='scored'?$sa->raw_score.'/'.$sa->maximum_score:'Pending' }}</td>@endforeach<td>{{ $session->raw_score===null?'Pending':$session->raw_score.'/'.$session->maximum_score }}</td><td>{{ $session->percentage===null?'—':number_format($session->percentage,1) }}</td></tr>@endforeach</tbody></table><div class="foot">Pending manual sections are not treated as zero and are excluded from a final aggregate until scored.</div></body></html>
